/** Shared document primitives. No I/O on import; every operation has an explicit root. */
import { CAMINS } from '../lib/arrel.mjs';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import yaml from 'js-yaml';
import { splitFrontmatter } from '../wiki/lib/frontmatter.mjs';

export const sha = value => crypto.createHash('sha256').update(value).digest('hex');
export const hashFile = file => sha(fs.readFileSync(file));
export const json = file => JSON.parse(fs.readFileSync(file, 'utf8'));
export const DESK = CAMINS.escriptori;
export const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
export const turnPattern = new RegExp(`^torn_${UUID}$`);
export const receiptPattern = new RegExp(`^sdp:(torn_${UUID}):(${UUID})$`);

export function canonical(file) {
  const abs = path.resolve(file);
  try { return fs.realpathSync(abs); } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    // A dangling symlink must not fall back to its lexical location.
    try { if (fs.lstatSync(abs).isSymbolicLink()) throw new Error(`Symlink sense destí: ${abs}`); }
    catch (e) { if (e.code !== 'ENOENT') throw e; }
    const parent = path.dirname(abs);
    if (parent === abs) throw error;
    return path.join(canonical(parent), path.basename(abs));
  }
}
export function inside(base, file) {
  const rel = path.relative(base, file);
  return rel === '' || (!rel.startsWith(`..${path.sep}`) && rel !== '..' && !path.isAbsolute(rel));
}
export function relativePath(root, file, cwd = root) {
  const actualRoot = canonical(root);
  const actual = canonical(path.resolve(cwd, file));
  if (!inside(actualRoot, actual)) throw new Error(`Ruta fora del repositori: ${file}`);
  return path.relative(actualRoot, actual).split(path.sep).join('/');
}
export function protectedPath(root, file, cwd = root) {
  const lexical = path.resolve(cwd, file);
  const actual = canonical(lexical);
  const base = canonical(path.join(root, DESK));
  const lexicalProtected = inside(path.resolve(root, DESK), lexical);
  const actualProtected = inside(base, actual);
  if (lexicalProtected && !actualProtected) throw new Error('Symlink que escapa de l’Escriptori');
  return (lexicalProtected || actualProtected) && actual.toLowerCase().endsWith('.md');
}
export function humanZone(rel) {
  return rel.toLowerCase().startsWith(`${DESK}/01_produccio/`);
}
export function parseDocument(raw) {
  const split = splitFrontmatter(raw);
  if (!split.hasFrontmatter || split.malformed) throw new Error('Frontmatter absent o no tancat');
  // JSON_SCHEMA keeps dates as strings, preserves booleans/numbers, rejects custom tags.
  const data = yaml.load(split.rawFrontmatter, { schema: yaml.JSON_SCHEMA, json: false });
  if (!data || Array.isArray(data) || typeof data !== 'object') throw new Error('Frontmatter ha de ser un mapa');
  if (/^\s*---\s*\n\s*[\w-]+:/.test(split.body)) throw new Error('DOS blocs de frontmatter');
  return { data, body: split.body };
}

// Fail closed on unknown JSON Schema constructs; support exactly the schema in this repo.
const allowed = new Set(['$schema', '$id', '$comment', 'title', 'description', 'type', 'properties',
  'required', 'additionalProperties', 'enum', 'const', 'items', 'uniqueItems', 'minItems', 'maxItems',
  'minLength', 'maxLength', 'pattern']);
export function checkSchema(schema) {
  if (!schema || typeof schema !== 'object' || Array.isArray(schema)) throw new Error('Esquema il·legible');
  for (const key of Object.keys(schema)) if (!allowed.has(key)) throw new Error(`Esquema no suportat: ${key}`);
  if (!['object', 'array', 'string', 'boolean', 'integer', 'number'].includes(schema.type)) throw new Error('Tipus d’esquema no suportat');
  if (schema.pattern) new RegExp(schema.pattern);
  for (const sub of Object.values(schema.properties || {})) checkSchema(sub);
  if (schema.items) checkSchema(schema.items);
}
export function validateSchema(data, schema, at = 'frontmatter') {
  const errors = [];
  const type = Array.isArray(data) ? 'array' : data === null ? 'null' : typeof data;
  if (schema.type === 'integer' ? !Number.isInteger(data) : type !== schema.type) return [`${at}: cal ${schema.type}`];
  if (schema.enum && !schema.enum.includes(data)) errors.push(`${at}: fora de l’enum`);
  if (Object.hasOwn(schema, 'const') && data !== schema.const) errors.push(`${at}: valor diferent de const`);
  if (type === 'string') {
    const len = [...data].length;
    if (schema.minLength !== undefined && len < schema.minLength) errors.push(`${at}: massa curt`);
    if (schema.maxLength !== undefined && len > schema.maxLength) errors.push(`${at}: massa llarg`);
    if (schema.pattern && !new RegExp(schema.pattern).test(data)) errors.push(`${at}: patró invàlid`);
  }
  if (type === 'array') {
    if (schema.minItems !== undefined && data.length < schema.minItems) errors.push(`${at}: falten elements`);
    if (schema.maxItems !== undefined && data.length > schema.maxItems) errors.push(`${at}: massa elements`);
    if (schema.uniqueItems && new Set(data.map(x => JSON.stringify(x))).size !== data.length) errors.push(`${at}: elements duplicats`);
    if (schema.items) data.forEach((x, i) => errors.push(...validateSchema(x, schema.items, `${at}[${i}]`)));
  }
  if (type === 'object') {
    for (const key of schema.required || []) if (!Object.hasOwn(data, key)) errors.push(`${at}: falta ${key}`);
    for (const [key, value] of Object.entries(data)) {
      if (schema.properties?.[key]) errors.push(...validateSchema(value, schema.properties[key], `${at}.${key}`));
      else if (schema.additionalProperties === false) errors.push(`${at}: propietat desconeguda ${key}`);
    }
  }
  return errors;
}
export function loadContract(root, {route: selected, templates = true} = {}) {
  const routerFile = path.join(root, '.agents/protocolledge.json');
  const schemaFile = path.join(root, 'tooling/wiki/schema.json');
  const router = json(routerFile), schema = json(schemaFile);
  checkSchema(schema);
  if (!router.version || router.onUnknown !== 'error' || !Array.isArray(router.rutes)) throw new Error('Router documental incomplet');
  const ids = new Set();
  for (const route of router.rutes) {
    if (!route.id || ids.has(route.id)) throw new Error('Ruta documental duplicada o absent');
    ids.add(route.id);
    if (!route.version || !schema.properties.type.enum.includes(route.tipus) || !route.seccions?.length) throw new Error(`Contracte incomplet: ${route.id}`);
    if (!templates || (selected && selected !== route.id)) continue;
    const file = relativePath(root, route.plantilla);
    const raw = fs.readFileSync(path.join(root, file), 'utf8');
    const template = parseDocument(raw);
    if (!['canonic', 'esborrany', 'actiu'].includes(template.data.status)) throw new Error(`Plantilla no viva: ${file}`);
    const blocks = [...raw.matchAll(/<!-- SDP:EIXIDA\s*\n([\s\S]*?)-->/g)];
    if (blocks.length !== 1) throw new Error(`Cal un bloc SDP:EIXIDA: ${file}`);
    const output = yaml.load(blocks[0][1], {schema: yaml.JSON_SCHEMA});
    if (output.type !== route.tipus) throw new Error(`Tipus divergent: ${route.id}`);
    route.output = output;
    route.templateText = raw;
    route.templateHash = sha(raw);
    route.fixedBlocks = Object.fromEntries((route.blocsFixos || []).map(name => {
      const value = sections(template.body).get(name);
      if (!value) throw new Error(`Bloc fix absent: ${route.id}: ${name}`);
      return [name, value];
    }));
  }
  return { router, schema, hash: sha(fs.readFileSync(routerFile) + '\n' + fs.readFileSync(schemaFile)) };
}
export function resolveRoute(contract, { route, intent, recipient } = {}) {
  const candidates = route ? contract.router.rutes.filter(r => r.id === route)
    : contract.router.rutes.filter(r => (r.quan?.intencio === intent || r.id === intent)
      && (!recipient || r.quan?.destinatari === recipient));
  if (candidates.length !== 1) throw new Error('Intenció desconeguda o ambigua; indica --route explícit');
  return candidates[0];
}
export function withoutCode(body) {
  let fence = null;
  return body.replace(/<!--[\s\S]*?-->/g, '').split('\n').filter(line => {
    const m = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    if (m) {
      if (!fence) fence = m[1];
      else if (m[1][0] === fence[0] && m[1].length >= fence.length) fence = null;
      return false;
    }
    return !fence;
  }).join('\n');
}
export function anchored(index, file) {
  const clean = withoutCode(index).replace(/`[^`]*`/g, '').replace(/\\(?=[|#])/g,'');
  const lexical = String(file).split(path.sep).join('/');
  const start = lexical.indexOf(`${CAMINS.wiki}/`);
  if (start < 0) return false;
  const target = path.posix.normalize(lexical.slice(start)).replace(/\.md$/, '');
  return [...clean.matchAll(/\[\[([^|\]#]+)(?:[|#][^\]]*)?\]\]/g)].some(m => {
    const ref = m[1].trim().replace(/\.md$/, '');
    // L'índex de l'Escriptori admet camí relatiu, des de Wiki o des del repo.
    // Un basename ambigu no acredita un document d'una altra carpeta.
    return [path.posix.join(DESK, ref), path.posix.join(CAMINS.wiki, ref), ref]
      .some(candidate => path.posix.normalize(candidate) === target);
  });
}
export function sections(body) {
  const clean = withoutCode(body);
  const chunks = [...clean.matchAll(/^##\s+(.+)\r?\n([\s\S]*?)(?=^##\s|$(?![\s\S]))/gm)];
  return new Map(chunks.map(m => [m[1].trim(), m[2].trim()]));
}
export function validateSections(body, route) {
  const found = sections(body), errors = [];
  for (const name of route.seccions) {
    const content = found.get(name);
    if (!content || /^\[pendent\]$/i.test(content)) errors.push(`Secció absent o pendent: ${name}`);
  }
  for (const [name, expected] of Object.entries(route.fixedBlocks || {})) {
    if (found.get(name) !== expected) errors.push(`Bloc normatiu alterat: ${name}`);
  }
  return errors;
}

export function validateRegister(body, contract) {
  const register = sections(body).get('Registre') || '';
  const fields = new Map([...register.matchAll(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*$/gm)].map(m => [m[1].trim(),m[2].trim()]));
  return (contract.router.registre || []).filter(k => !fields.get(k) || fields.get(k) === '[pendent]').map(k => `Registre: falta ${k}`);
}

// Content-addressed snapshots are durable evidence, not authorisation or a secret signature.
export function saveContract(root, contract) {
  const payload = JSON.stringify(contract);
  const digest = sha(payload);
  const dir = path.join(root, '.agents/runtime/contracts');
  fs.mkdirSync(dir, {recursive:true});
  const file = path.join(dir, `${digest}.json`);
  if (fs.existsSync(file)) {
    if (fs.readFileSync(file,'utf8') !== payload) throw new Error('Snapshot immutable alterat');
  } else fs.writeFileSync(file,payload,{flag:'wx'});
  return digest;
}
export function readContract(root, digest, read) {
  if (!/^[a-f0-9]{64}$/.test(digest)) throw new Error('Identificador de snapshot invàlid');
  const rel=`.agents/runtime/contracts/${digest}.json`;
  const raw=read ? read(rel) : fs.readFileSync(path.join(root,rel),'utf8');
  if (sha(raw)!==digest) throw new Error('Snapshot immutable alterat');
  const contract=JSON.parse(raw);
  checkSchema(contract.schema);
  return contract;
}
export function templateParity(contract) {
  const errors=[];
  for (const route of contract.router.rutes) {
    const actual=[...sections(parseDocument(route.templateText).body).keys()];
    if (JSON.stringify(actual)!==JSON.stringify(route.seccions)) errors.push(`${route.id}: encapçalaments divergents: ${actual.join(' | ')}`);
  }
  return errors;
}

/** Escriptura de draft i àncora: revalida en executar, mai confia en el hook.
 * L'índex es llig per descriptor O_NOFOLLOW i es reemplaça amb rename; mai
 * escrivim al seu inode original, que un altre procés podria haver reenllaçat.
 */
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { CAMINS } from '../lib/arrel.mjs';
import { checkTaula } from '../gates/porta-olivera.mjs';

const same = (a, b) => a.dev === b.dev && a.ino === b.ino;
const regular = stat => stat.isFile() && stat.nlink === 1;
const failure = () => new Error('Destí documental substituït, enllaçat o fora de l’arrel.');

function parents(root, file, create = false) {
  const rel = path.relative(root, file);
  if (!rel || rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) throw failure();
  let current = root;
  for (const part of rel.split(path.sep).slice(0, -1)) {
    current = path.join(current, part);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) {
      if (error.code !== 'ENOENT') throw error;
      if (!create) return;
      fs.mkdirSync(current); stat = fs.lstatSync(current);
    }
    if (!stat.isDirectory() || stat.isSymbolicLink() || fs.realpathSync(current) !== current) throw failure();
  }
}
function openIndex(root) {
  const file = path.join(root, CAMINS.indexEscriptori);
  parents(root, file);
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  try {
    const stat = fs.fstatSync(fd);
    if (!regular(stat)) throw failure();
    parents(root, file);
    const named = fs.lstatSync(file);
    if (!regular(named) || named.isSymbolicLink() || !same(stat, named)) throw failure();
    return { file, fd, stat, content: fs.readFileSync(fd, 'utf8') };
  } catch (error) { fs.closeSync(fd); throw error; }
}
function assertOwned(root, file, stat, fd) {
  parents(root, file);
  const named = fs.lstatSync(file), opened = fs.fstatSync(fd);
  if (!regular(named) || !regular(opened) || named.isSymbolicLink() || !same(named, stat) || !same(opened, stat)) throw failure();
}
function removeOwned(root, file, stat) {
  // Rollback mai elimina un fitxer que una altra operació ha posat al mateix nom.
  try {
    parents(root, file);
    const named = fs.lstatSync(file);
    if (!named.isSymbolicLink() && same(named, stat)) fs.unlinkSync(file);
  } catch (error) { if (error.code !== 'ENOENT') return; }
}
export function checkDraftDestinations(root, file) {
  root = fs.realpathSync(root);
  parents(root, file);
  try {
    fs.lstatSync(file);
    const error = new Error('EEXIST: el draft ja existix.'); error.code = 'EEXIST'; throw error;
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
  const index = openIndex(root);
  fs.closeSync(index.fd);
}
function indexProse(index) {
  // Conserva offsets per inserir sense alterar comentaris ni exemples de codi.
  const mask = text => text.replace(/[^\r\n]/g, ' ');
  let fence = null;
  return index.replace(/<!--[\s\S]*?-->/g, mask).split(/(?<=\n)/).map(line => {
    const mark = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    if (mark) {
      if (!fence) fence = mark[1];
      else if (mark[1][0] === fence[0] && mark[1].length >= fence.length) fence = null;
      return mask(line);
    }
    return fence ? mask(line) : line;
  }).join('').replace(/`[^`]*`/g, mask);
}
function anchorDraft(index, anchor, firstLevel) {
  if (!firstLevel) return indexProse(index).includes(anchor) ? index : `${index}\n- ${anchor}\n`;
  const prose = indexProse(index);
  const active = /^##[ \t]+Activitat en curs[^\n]*(?:\r?\n|$)/m.exec(prose);
  if (!active) return `${index}\n## Activitat en curs\n\n- ${anchor}\n`;
  const start = active.index + active[0].length;
  const next = /^##[ \t]/m.exec(prose.slice(start));
  const end = next ? start + next.index : index.length;
  if (prose.slice(start, end).includes(anchor)) return index;
  return `${index.slice(0, start)}\n- ${anchor}\n${index.slice(start)}`;
}
export function writeIndexedDraft(root, file, content, { requireCleanTable = false } = {}) {
  root = fs.realpathSync(root);
  checkDraftDestinations(root, file);
  const lock = path.join(root, CAMINS.agents, 'runtime', 'document-create.lock');
  parents(root, lock);
  const lockFd = fs.openSync(lock, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, 0o600);
  const lockStat = fs.fstatSync(lockFd);
  let index, created, temporary, committed = false;
  try {
    assertOwned(root, lock, lockStat, lockFd);
    index = openIndex(root);
    // Revalida dins del lock: context pot haver emés el rebut abans que un
    // altre actor deixe un document nou sense classificar. No es mou res.
    if (requireCleanTable) {
      const taula = checkTaula(root);
      if (!taula.valid) throw new Error(`Convocatòria amb Escriptori brut:\n${taula.errors.join('\n')}`);
    }
    parents(root, file, true);
    const fd = fs.openSync(file, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, 0o600);
    created = { fd, stat: fs.fstatSync(fd) };
    assertOwned(root, file, created.stat, fd);
    fs.writeFileSync(fd, content, 'utf8'); fs.fsyncSync(fd);
    const relative = path.relative(path.dirname(index.file), file).split(path.sep).join('/').replace(/\.md$/, '');
    const anchor = `[[${relative}]]`;
    const anchored = anchorDraft(index.content, anchor, path.dirname(file) === path.join(root, CAMINS.escriptori));
    if (anchored !== index.content) {
      const tempFile = `${index.file}.${randomUUID()}.tmp`;
      parents(root, tempFile);
      const tempFd = fs.openSync(tempFile, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, index.stat.mode & 0o777);
      temporary = { file: tempFile, fd: tempFd, stat: fs.fstatSync(tempFd) };
      assertOwned(root, tempFile, temporary.stat, tempFd);
      fs.writeFileSync(tempFd, anchored, 'utf8'); fs.fsyncSync(tempFd);
    }
    // CAS de bytes i inode: preserva també les edicions concurrents legítimes.
    const latest = openIndex(root);
    try { if (!same(index.stat, latest.stat) || index.content !== latest.content) throw failure(); }
    finally { fs.closeSync(latest.fd); }
    assertOwned(root, index.file, index.stat, index.fd);
    assertOwned(root, file, created.stat, created.fd);
    if (temporary) {
      assertOwned(root, temporary.file, temporary.stat, temporary.fd);
      fs.renameSync(temporary.file, index.file);
    }
    committed = true;
  } finally {
    if (index) fs.closeSync(index.fd);
    if (created) {
      fs.closeSync(created.fd);
      if (!committed) removeOwned(root, file, created.stat);
    }
    if (temporary) { fs.closeSync(temporary.fd); removeOwned(root, temporary.file, temporary.stat); }
    fs.closeSync(lockFd); removeOwned(root, lock, lockStat);
  }
}

/** Persistent per-turn records. Locks never silently recover; failed writes leave the prior record intact. */
import { CAMINS } from '../lib/arrel.mjs';
import { checkTaula } from '../gates/porta-olivera.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { DESK, canonical, inside, relativePath, humanZone, hashFile, sha, json, turnPattern, receiptPattern,
  loadContract, saveContract, readContract, resolveRoute, parseDocument, anchored, validateSchema, validateSections, validateRegister } from './core.mjs';

const STORE = '.agents/runtime/turns';
function recordPath(root, id) {
  if (!turnPattern.test(id)) throw new Error('Identificador de torn invàlid');
  const target = path.join(root, STORE, `${id}.json`);
  if (!inside(canonical(root), canonical(target))) throw new Error('Registre fora del repositori');
  return target;
}
export function inventory(root, {files=[]} = {}) {
  const out = {};
  const skip = new Set(['node_modules', '.git', 'dist', '90_arxiu_historic', '.obsidian', 'runtime', '__pycache__']);
  function walk(rel) {
    const file = path.join(root, rel);
    if (!fs.existsSync(file)) return;
    const stat = fs.lstatSync(file);
    if (stat.isSymbolicLink()) { out[rel] = sha(`symlink:${fs.readlinkSync(file)}`); return; }
    if (stat.isDirectory()) {
      for (const e of fs.readdirSync(file).sort()) if (!skip.has(e)) walk(`${rel}/${e}`);
    } else if (stat.isFile()) out[rel] = hashFile(file);
  }
  for (const rel of ['src', 'tooling', 'scripts', 'tests', '.agents', '.codex', '.claude', '.github', '.husky', CAMINS.wiki,
    'package.json', 'package-lock.json', 'AGENTS.md', 'CLAUDE.md', 'vite.config.js', '.gitignore']) walk(rel);
  for (const file of files) {
    const rel=relativePath(root,file);
    if(fs.existsSync(path.join(root,rel))) out[rel]=hashFile(path.join(root,rel));
  }
  delete out['.agents/TORN_ACTIU.json'];
  return out;
}
export function changes(before, after) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].filter(p => before[p] !== after[p]).sort();
}
export function readTurn(root, id, { closed = false, now = Date.now() } = {}) {
  const turn = json(recordPath(root, id));
  if (turn.turn_id !== id || turn.schema !== 'sdp.turn.v1' || !['opened', 'context_loaded', 'planned', 'verified', 'closed'].includes(turn.state)) throw new Error('Registre de torn invàlid');
  if (turn.state === 'closed' && !closed) throw new Error('Torn ja tancat');
  if (turn.state !== 'closed' && (!Number.isFinite(Date.parse(turn.expiresAt)) || Date.parse(turn.expiresAt) <= now)) throw new Error('Torn caducat');
  if (!turn.receipts || !turn.initial || !Array.isArray(turn.history)) throw new Error('Registre de torn incomplet');
  return turn;
}
function atomic(file, value) {
  const tmp = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, {flag:'wx', mode:0o600});
    fs.renameSync(tmp, file);
  } finally { if (fs.existsSync(tmp)) fs.unlinkSync(tmp); }
}
export function mutateTurn(root, id, operation) {
  const file = recordPath(root, id), lock = `${file}.lock`;
  const fd = fs.openSync(lock, 'wx', 0o600);
  try {
    const turn = readTurn(root, id);
    const result = operation(turn);
    turn.revision += 1;
    turn.updatedAt = new Date().toISOString();
    atomic(file, turn);
    return result ?? turn;
  } finally { fs.closeSync(fd); fs.unlinkSync(lock); }
}
function move(turn, state, action) {
  turn.state = state;
  turn.history.push({state, action, at:new Date().toISOString()});
}
export function openTurn(root, { actor = 'agent-local', scope = 'code' } = {}) {
  if (fs.existsSync(path.join(root, '.agents/SDP-LOCK'))) throw new Error('SDP-LOCK actiu');
  if (!['code', 'documents'].includes(scope)) throw new Error('Abast desconegut');
  const contract = loadContract(root, {templates:false});
  const turn_id = `torn_${randomUUID()}`;
  const now = new Date().toISOString();
  const turn = {schema:'sdp.turn.v1', turn_id, actor, scope, state:'opened', revision:0,
    createdAt:now, updatedAt:now, expiresAt:new Date(Date.now()+86400000).toISOString(),
    contractHash:contract.hash, humanInventoryVersion:1, initial:inventory(root), receipts:{}, plan:null, verification:null,
    history:[{state:'opened', action:'open', at:now}]};
  const file = recordPath(root, turn_id);
  fs.mkdirSync(path.dirname(file), {recursive:true});
  fs.writeFileSync(file, `${JSON.stringify(turn, null, 2)}\n`, {flag:'wx', mode:0o600});
  return turn;
}
export function deliverContext(root, id, {route:routeId, file}) {
  const contract = loadContract(root, {route:routeId}), route = resolveRoute(contract, {route:routeId});
  const rel = relativePath(root, file);
  if (!(route.destins || [DESK]).some(dir=>rel.startsWith(`${dir}/`)) || humanZone(rel) || path.basename(rel) === '00_index_escriptori.md') throw new Error('Destí de document no autoritzat');
  if (!/^\d{6}_\d{4}_[a-z0-9_]+\.md$/.test(path.basename(rel))) throw new Error('Nom termodinàmic invàlid');
  // Convocar agents exigix taula neta també fora d'un hook; una auditoria pot
  // documentar una taula bruta. create revalida ací, encara que ja tinga context.
  if (['prompt.local', 'prompt.consell'].includes(route.id)) {
    const taula = checkTaula(root);
    if (!taula.valid) throw new Error(`Convocatòria amb Escriptori brut:\n${taula.errors.join('\n')}`);
  }
  return mutateTurn(root, id, turn => {
    const receiptId = randomUUID();
    const receipt = {id:receiptId, route:route.id, routeVersion:route.version, file:rel,
      contractSnapshot:saveContract(root,contract), template:route.plantilla, templateHash:route.templateHash, issuedAt:new Date().toISOString()};
    turn.receipts[receiptId] = receipt;
    // New context invalidates verification, but retains an already bound plan.
    turn.verification = null;
    move(turn, turn.plan ? 'planned' : 'context_loaded', 'context');
    return {reflex:`sdp:${id}:${receiptId}`, route, template:route.templateText};
  });
}
export function validateDocument(root, content, file, { closed = false, readRecord, readSnapshot } = {}) {
  const errors = [];
  try {
    const parsed = parseDocument(content);
    const rel = relativePath(root, file);
    // The canonical desktop index is structural, never a substitute for a formal document.
    if (rel === `${DESK}/00_index_escriptori.md` && parsed.data.type === 'index') return validateSchema(parsed.data,loadContract(root,{templates:false}).schema);
    const m = typeof parsed.data.reflex === 'string' && receiptPattern.exec(parsed.data.reflex);
    if (!m) {
      errors.push('reflex: cal un rebut persistent emés per document.mjs context');
      errors.push(...validateSchema(parsed.data, loadContract(root, {templates: false}).schema));
    } else {
      const turn = readRecord ? readRecord(m[1]) : readTurn(root, m[1], {closed});
      const receipt = turn.receipts[m[2]];
      if (!receipt || receipt.id !== m[2] || receipt.file !== rel) throw new Error('Rebut absent o vinculat a un altre document');
      const contract = receipt.contractSnapshot ? readContract(root,receipt.contractSnapshot,readSnapshot) : loadContract(root,{route:receipt.route});
      if (!receipt.contractSnapshot && turn.contractHash !== contract.hash) throw new Error('Contracte del rebut caducat');
      errors.push(...validateSchema(parsed.data, contract.schema));
      const route = resolveRoute(contract, {route:receipt.route});
      if (receipt.templateHash !== route.templateHash || receipt.routeVersion !== route.version) throw new Error('Plantilla del rebut canviada');
      if (parsed.data.type !== route.tipus) errors.push('type: no correspon a la ruta del rebut');
      errors.push(...validateSections(parsed.body, route), ...validateRegister(parsed.body, contract));
      if (turn.state === 'closed' && turn.verification?.files?.[rel] !== sha(content)) errors.push('Artefacte modificat després del tancament');
    }
  } catch (e) { errors.push(e.message); }
  return errors;
}
export function bindPlan(root, id, file) {
  const rel = relativePath(root, file);
  const raw = fs.readFileSync(path.join(root, rel), 'utf8');
  const parsed = parseDocument(raw);
  const contract = loadContract(root);
  const errors = validateSchema(parsed.data, contract.schema);
  if (errors.length || parsed.data.type !== 'document') throw new Error(`Pla invàlid: ${errors.join('; ')}`);
  if (!rel.startsWith(`${DESK}/`) || humanZone(rel)) throw new Error('El pla ha de viure a l’Escriptori');
  return mutateTurn(root, id, turn => {
    if (!Object.keys(turn.receipts).length) throw new Error('Cal entregar context abans de vincular el pla');
    turn.plan = {file:rel, hash:sha(raw)};
    turn.verification = null;
    move(turn, 'planned', 'bind-plan');
  });
}
export function checkTurn(root, id, {turn:provided} = {}) {
  const errors = [];
  const turn = provided || readTurn(root, id);
  const contract = loadContract(root,{templates:false});
  if (!Object.values(turn.receipts).every(r=>r.contractSnapshot) && turn.contractHash !== contract.hash) errors.push('Contracte canviat durant el torn');
  if (!turn.plan || !fs.existsSync(path.join(root,turn.plan.file)) || hashFile(path.join(root, turn.plan.file)) !== turn.plan.hash) errors.push(`Pla absent o modificat: ${turn.plan?.file || '(sense pla)'}`);
  if (!['planned', 'verified'].includes(turn.state)) errors.push('El torn encara no està planificat');
  const current = inventory(root,{files:Object.values(turn.receipts).map(r=>r.file)}), changed = changes(turn.initial, current);
  // Explicit ownership avoids importing another agent's documents into this turn.
  // Human-zone and scope checks still use the complete repository delta.
  const owned = turn.ownedPaths ? new Set([...turn.ownedPaths,...Object.values(turn.receipts).map(r=>r.file)]) : null;
  const documents = new Set([...changed.filter(p=>!humanZone(p)).filter(p=>!turn.relocated?.includes(p)).filter(p=>!owned || owned.has(p)).filter(p => p.startsWith(`${DESK}/`) && p.endsWith('.md')),
    ...Object.values(turn.receipts).map(r => r.file)]);
  if (turn.scope === 'documents' && changed.some(p => /^(src|tooling|scripts|tests)\//.test(p) || /^package(?:-lock)?\.json$/.test(p))) errors.push('Canvis de codi fora de l’abast documental');
  for (const p of ['.agents/ESTAT.md', '.agents/LEDGER.md']) {
    if (current[p] === turn.initial[p] || !fs.readFileSync(path.join(root,p),'utf8').includes(id)) errors.push(`${p}: falta el relleu d’aquest torn`);
  }
  const humanBefore=turn.humanBaseline?.files || (turn.humanInventoryVersion===1 ? Object.fromEntries(Object.entries(turn.initial).filter(([p])=>humanZone(p))) : null);
  if(!humanBefore) errors.push('Vigilància humana sense inventari inicial; cal una migració explícita observada');
  else for(const file of changes(humanBefore,Object.fromEntries(Object.entries(current).filter(([p])=>humanZone(p))))) errors.push(`Zona humana modificada: ${file}`);
  const index = fs.readFileSync(path.join(root, DESK, '00_index_escriptori.md'),'utf8');
  for (const file of documents) {
    if (humanZone(file)) { errors.push(`Zona humana modificada: ${file}`); continue; }
    if (!fs.existsSync(path.join(root,file))) { errors.push(`Document eliminat sense relleu: ${file}`); continue; }
    const raw = fs.readFileSync(path.join(root,file),'utf8');
    errors.push(...validateDocument(root,raw,file,{readRecord:otherId=>otherId===id?turn:readTurn(root,otherId,{closed:true})}).map(e=>`${file}: ${e}`));
    if (file !== `${DESK}/00_index_escriptori.md` && !anchored(index,file)) errors.push(`Document sense àncora: ${file}`);
  }
  return {valid:errors.length===0, errors, current, changed, turn};
}
export function sealTurn(root, id, runChecks, {close = false} = {}) {
  return mutateTurn(root, id, turn => {
    const checked = checkTurn(root, id, {turn});
    if (!checked.valid) throw new Error(checked.errors.join('\n'));
    const result = runChecks(turn);
    if (!result.valid) throw new Error(result.errors.join('\n'));
    const after = inventory(root,{files:Object.values(turn.receipts).map(r=>r.file)});
    if (changes(checked.current,after).length) throw new Error('La comprovació ha modificat fitxers o hi ha escriptura concurrent');
    turn.verification = {at:new Date().toISOString(), files:after, checks:result.checks};
    move(turn,'verified','verify');
    if (close) move(turn,'closed','close');
    return {valid:true, turn_id:id, state:turn.state, checks:result.checks};
  });
}

// Ownership is explicit; absence keeps the conservative legacy whole-tree check.
export function ownPaths(root,id,files) {
  const paths=files.map(file=>relativePath(root,file));
  if(paths.some(humanZone)) throw new Error('No es pot reclamar la zona humana');
  return mutateTurn(root,id,turn=>{
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]),...paths])];
    turn.verification=null;
    turn.history.push({action:'own-paths',files:paths,at:new Date().toISOString()});
  });
}
// A handoff registers a move already performed; it never fabricates a past reading.
export function handoffDocument(root,id,from,to) {
  const source=relativePath(root,from), target=relativePath(root,to);
  if(humanZone(source)||humanZone(target)) throw new Error('Zona humana protegida');
  if(![DESK,CAMINS.actes,CAMINS.arxiuHistoric].some(dir=>target.startsWith(`${dir}/`))) throw new Error('Destí de relleu no autoritzat');
  if(fs.existsSync(path.join(root,source))) throw new Error('La ruta original encara existeix');
  const raw=fs.readFileSync(path.join(root,target),'utf8'), digest=sha(raw);
  const match=receiptPattern.exec(parseDocument(raw).data.reflex||'');
  if(!match||match[1]!==id) throw new Error('Identitat del relleu divergent');
  return mutateTurn(root,id,turn=>{
    const receipt=turn.receipts[match[2]];
    const prior = receipt?.file===target && receipt.moves?.find(move=>move.from===source && move.to===target && move.hash===digest);
    if(!receipt || (receipt.file!==source && !prior)) throw new Error('Rebut del relleu absent');
    if(turn.plan?.file===source && turn.plan.hash!==digest) throw new Error('Pla modificat durant el relleu');
    // El reflex identifica el rebut immutable que va fer nàixer el document.
    // Captura IDs exactes: un context posterior per a reutilitzar source no és
    // cap lectura d'este arxiu. Legacy: prefix d'emissió, sense fiar-se del rellotge.
    const emitted = Object.values(turn.receipts);
    const original = emitted.slice(0, emitted.indexOf(receipt)+1).filter(candidate=>
      candidate.file===source && candidate.route===receipt.route && candidate.contractSnapshot===receipt.contractSnapshot);
    const receiptIds = prior?.receiptIds || original.map(candidate=>candidate.id);
    for(const owned of emitted.filter(candidate=>candidate.file===source && receiptIds.includes(candidate.id))) {
      owned.file=target;
      owned.moves=[...(owned.moves||[]),{from:source,to:target,hash:digest,at:new Date().toISOString(),receiptIds}];
    }
    if(turn.plan?.file===source) turn.plan.file=target;
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]).filter(p=>p!==source),target])];
    // Preserve source history, while recognising that its absence is an intentional handoff.
    turn.relocated=[...(turn.relocated||[]),source];
    turn.verification=null;
    move(turn,turn.plan?'planned':'context_loaded','handoff');
  });
}
export function protectedTurnFiles(root) {
  const dir=path.join(root,STORE), out=new Set();
  if(!fs.existsSync(dir)) return out;
  for(const name of fs.readdirSync(dir).filter(n=>n.endsWith('.json'))) {
    const turn=json(path.join(dir,name));
    if(!turnPattern.test(turn.turn_id)||!Array.isArray(turn.history)||!turn.receipts) throw new Error(`Torn il·legible: ${name}`);
    // Closed receipts are protected too until an explicit archival handoff is supported.
    if(turn.plan?.file) out.add(turn.plan.file);
    for(const receipt of Object.values(turn.receipts)) out.add(receipt.file);
  }
  return out;
}

export function startHumanWatch(root,id) {
 return mutateTurn(root,id,turn=>{
  if(turn.humanInventoryVersion===1||turn.humanBaseline) throw new Error('Inventari humà ja establit; no es pot reiniciar');
  turn.humanBaseline={at:new Date().toISOString(),provenance:'observed-at-upgrade',files:Object.fromEntries(Object.entries(inventory(root)).filter(([file])=>humanZone(file)))};
  turn.history.push({action:'start-human-watch',at:turn.humanBaseline.at,note:'Observació actual; no acredita vigilància anterior ni autoria dels canvis previs.'});
 });
}

export function acknowledgeHumanZoneChanges(root, id, note = 'Reconeixement explícit de canvis a la zona humana') {
  return mutateTurn(root, id, turn => {
    if (!turn.humanBaseline) throw new Error('No hi ha vigilància humana activa al torn');
    const currentHumanZone = Object.fromEntries(Object.entries(inventory(root)).filter(([file]) => humanZone(file)));
    const changedFiles = changes(turn.humanBaseline.files, currentHumanZone);
    if (!changedFiles.length) throw new Error('No hi ha canvis a la zona humana per a reconéixer');

    turn.humanBaseline.files = currentHumanZone;
    turn.humanBaseline.at = new Date().toISOString();
    turn.humanBaseline.provenance = 'acknowledged';
    turn.verification = null;
    turn.history.push({ action: 'acknowledge-human-zone-changes', files: changedFiles, at: turn.humanBaseline.at, note });
  });
}

#!/usr/bin/env node
/** Porta Olivera · higiene d'Escriptori en la transició Pla → Petorreta.
 *
 *  El problema que resol, dit sense adornar-lo: la precondició d'higiene («neteja
 *  l'Escriptori i escriu el Pla abans de cridar les altres IAs») vivia a les
 *  Lliçons d'una skill, i el moment de decisió té davant un altre document. Una
 *  regla que ha de disparar en el moment X ha de viure al canal que corre en el
 *  moment X. Qualsevol altra ubicació és decorativa.
 *
 *  Per això açò no és un recordatori: és una porta `PreToolUse`. Quan algú escriu
 *  una petorreta a l'Escriptori, comprova tres coses i bloqueja si no es complixen:
 *
 *    1. L'Escriptori està net (`checkTaula`, la definició única d'AGENTS §0.1):
 *       cap prompt, auditoria, pla o bundle consumit de jornades anteriors solt
 *       damunt la taula, la Safata d'Entrada buida, cada document ancorat a
 *       l'índex i cap àncora a un document absent.
 *    2. Hi ha un Pla d'Implementació d'aquesta jornada: la pissarra compartida
 *       existix abans de convocar ningú.
 *    3. La petorreta porta la secció 0 i cap casella sense marcar. La secció es
 *       pot dir «0. Abans de generar» o «0. Preflight», que és el nom que du la
 *       plantilla `prompt_local.md`: un prompt fet bé des de la plantilla no pot
 *       quedar bloquejat pel nom de la capçalera.
 *
 *  Viu per declaració, no per data (260930). A les 00:00 el rellotge convertia en
 *  brossa el prompt que s'estava executant. Ara decidix qui treballa: tot document
 *  llistat davall d'una capçalera «## Activitat en curs» de l'índex continua viu,
 *  siga del dia que siga, i `ranci()` no el toca. La tria és explícita i
 *  auditable: l'informe la mostra sencera.
 *
 *  L'informe (`npm run porta:olivera`) jutja la taula, no la petorreta: ix amb 0
 *  quan `checkTaula` és vàlid. El «pla de hui» només té sentit quan s'escriu una
 *  petorreta, i per això el demana el hook i no l'informe; si no, un Escriptori
 *  acabat de netejar al matí no passaria mai abans del primer pla.
 *
 *  No esborra res mai. `--arxiva` mou a `90_arxiu_historic/` i despenja les
 *  entrades de l'índex, i és una ordre explícita: AGENTS §5 prohibix l'esborrat
 *  automàtic i el trasllat silenciós d'allò que encara pot estar viu.
 *
 *  Ús:
 *    porta-olivera.mjs [--informe]          # auditoria de l'Escriptori (eixida 1 si brut); mai llig stdin
 *    porta-olivera.mjs --hook               # hook: llig el payload per stdin
 *    porta-olivera.mjs --arxiva [--sec]     # mou els consumits de jornades anteriors
 *    porta-olivera.mjs --arxiva --nom F.md [--nom G.md] [--sec]
 *                                           # mou documents de torn concrets, també d'avui
 *
 *  El mode hook és explícit: sense bandera, `readFileSync(0)` esperava un EOF que
 *  un terminal (o un pipe que ningú tanca) no envia mai, i la porta es penjava
 *  just quan la skill manava executar-la.
 */
import { CAMINS, arrelSegura, esMain } from '../lib/arrel.mjs';
import fs from 'node:fs';
import path from 'node:path';
import tty from 'node:tty';

// La ubicació de l'eina resol l'arrel. Conservar l'error permet importar les
// funcions amb una arrel explícita en fixtures, sense donar cap verd implícit.
let errorArrel = null;
export const ARREL = (() => {
  try { return process.env.SDP_ARREL ? path.resolve(process.env.SDP_ARREL) : arrelSegura(); }
  catch (error) { errorArrel = error; return null; }
})();
function arrelPerDefecte() {
  if (ARREL) return ARREL;
  throw errorArrel;
}
const ESCRIPTORI = CAMINS.escriptori;
const ARXIU = CAMINS.arxiuHistoric;
const INDEX = CAMINS.indexEscriptori;

/** Categories de treball d'un torn: naixen, servixen i se'n van a l'arxiu. */
export const TRANSITORIES = /^(prompt|macro_prompt|micro_prompt|petorreta|auditoria|informe|bundle|macro_bundle|micro_bundle|pla|acta|tasques)$/;

const NOM = /^(\d{6})_(\d{4})_([a-z0-9]+(?:_[a-z0-9]+)*)\.md$/;

/** Capçalera que declara vius els documents que llista. N'hi pot haver més d'una, amb sufix. */
const ACTIVITAT = /^##[ \t]+Activitat en curs[^\n]*\n([\s\S]*?)(?=^##[ \t]|(?![\s\S]))/gm;

/** Secció 0 d'una petorreta: el nom de les proves antigues i el de la plantilla viva. */
const SECCIO_ZERO = /^##[ \t]+0\.[ \t]+(?:Abans de generar|Preflight)[^\n]*\n([\s\S]*?)(?=^#{1,2}[ \t]+|(?![\s\S]))/m;

/** `aammdd` d'avui, en hora local: és el segell que porten els noms de fitxer. */
export function avui(ara = new Date()) {
  const p = (n) => String(n).padStart(2, '0');
  return `${p(ara.getFullYear() % 100)}${p(ara.getMonth() + 1)}${p(ara.getDate())}`;
}

/** Documents solts de l'Escriptori, amb data, categoria i cognom. */
export function inventari(arrel = arrelPerDefecte()) {
  const dir = path.join(arrel, ESCRIPTORI);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isFile() && !e.name.startsWith('.') && e.name.endsWith('.md'))
    .map((e) => {
      const m = NOM.exec(e.name);
      if (!m) return null;
      const [, data, hora, resta] = m;
      const categoria = resta.startsWith('pla_implementacio') ? 'pla' : resta.split('_')[0];
      return { nom: e.name, rel: `${ESCRIPTORI}/${e.name}`, data, hora, categoria, resta };
    })
    .filter(Boolean);
}

/**
 * Noms (sense `.md`) que l'índex declara vius davall de qualsevol «## Activitat en
 * curs». Comparteix resolució amb `ancoratge()`: només compta si el camí
 * resol al primer nivell; un homònim d'una altra carpeta no protegix la taula.
 */
export function vius(arrel = arrelPerDefecte()) {
  const p = path.join(arrel, INDEX);
  const text = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
  const noms = new Set();
  for (const bloc of prosaIndex(text).matchAll(ACTIVITAT)) {
    for (const a of bloc[1].matchAll(/\[\[([^\]]+)\]\]/g)) {
      const nom = nomPrimerNivell(referent(a[1]));
      if (nom) noms.add(nom);
    }
  }
  return noms;
}

/** El que hauria d'estar a l'arxiu: categoria de torn, data anterior a hui i cap declaració de viu. */
export function ranci(arrel = arrelPerDefecte(), dia = avui()) {
  const viu = vius(arrel);
  return inventari(arrel).filter((d) => TRANSITORIES.test(d.categoria) && d.data < dia && !viu.has(d.nom.replace(/\.md$/, '')));
}

/** Pissarra compartida d'aquesta jornada. */
export function plaDeHui(arrel = arrelPerDefecte(), dia = avui()) {
  return inventari(arrel).filter((d) => /^pla_implementacio(?:_|$)/.test(d.resta) && d.data === dia);
}

/**
 * Elements de la Safata d'Entrada, que ha d'estar sempre buida (AGENTS §12). La
 * carpeta es busca sense distingir caixa: el codi en conserva `00_Bandeja_d_Entrada`
 * i el disc du `00_bandeja_d_entrada`, i a Linux una comparació exacta no la veuria.
 */
export function safata(arrel = arrelPerDefecte()) {
  const dir = path.join(arrel, ESCRIPTORI);
  if (!fs.existsSync(dir)) return { carpeta: null, elements: [] };
  const carpeta = fs.readdirSync(dir, { withFileTypes: true })
    .find((e) => e.isDirectory() && /^00_bandeja_d_entrada$/i.test(e.name));
  if (!carpeta) return { carpeta: null, elements: [] };
  const elements = fs.readdirSync(path.join(dir, carpeta.name)).filter((n) => !n.startsWith('.')).sort();
  return { carpeta: `${ESCRIPTORI}/${carpeta.name}`, elements };
}

/** Prosa amb offsets intactes: comentaris i codi no acrediten cap àncora. */
function prosaIndex(text) {
  const mask = part => part.replace(/[^\r\n]/g, ' ');
  let fence = null;
  return text.replace(/<!--[\s\S]*?-->/g, mask).split(/(?<=\n)/).map(line => {
    const mark = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    if (mark) {
      if (!fence) fence = mark[1];
      else if (mark[1][0] === fence[0] && mark[1].length >= fence.length) fence = null;
      return mask(line);
    }
    return fence ? mask(line) : line;
  }).join('').replace(/`[^`]*`/g, mask);
}
const referent = raw => raw.replace(/\\(?=[|#])/g,'').split(/[|#]/)[0].trim().replace(/\.md$/, '');
function nomPrimerNivell(ref) {
  const normalized = path.posix.normalize(ref);
  for (const candidate of [path.posix.join(ESCRIPTORI,normalized),path.posix.join(CAMINS.wiki,normalized),normalized]) {
    if (path.posix.dirname(candidate) === ESCRIPTORI) return path.posix.basename(candidate);
  }
  return null;
}

/** Documents de l'Escriptori sense àncora a l'índex, i àncores a documents absents. */
export function ancoratge(arrel = arrelPerDefecte()) {
  const indexPath = path.join(arrel, INDEX);
  const text = fs.existsSync(indexPath) ? fs.readFileSync(indexPath, 'utf8') : '';
  const ancores = [...prosaIndex(text).matchAll(/\[\[([^\]]+)\]\]/g)].map((m) => referent(m[1]));
  const docs = inventari(arrel).filter((d) => d.nom !== '00_index_escriptori.md');
  const noms = new Set(docs.map((d) => d.nom.replace(/\.md$/, '')));
  const ancorats = new Set(ancores.map(nomPrimerNivell).filter(Boolean));
  return {
    senseAncora: docs.filter((d) => !ancorats.has(d.nom.replace(/\.md$/, ''))).map((d) => d.nom),
    // Només comptem àncores planes: les que porten `/` apunten fora de l'Escriptori.
    fantasma: ancores.filter((a) => !a.includes('/') && !noms.has(a) && a !== '00_index_escriptori')
  };
}

/**
 * Escriptori net: la definició única (AGENTS §0.1) i el que jutja l'informe.
 * Brossa, Safata i àncores; el «pla de hui» no hi entra, és cosa de la petorreta.
 */
export function checkTaula(arrel = arrelPerDefecte(), { dia = avui() } = {}) {
  const errors = [];
  for (const [rel, directory] of [[ESCRIPTORI, true], [INDEX, false]]) {
    try {
      const stat = fs.lstatSync(path.join(arrel, rel));
      if (stat.isSymbolicLink() || !(directory ? stat.isDirectory() : stat.isFile()))
        errors.push(`Estructura de l'Escriptori invàlida: ${rel}`);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
      errors.push(`Estructura de l'Escriptori absent: ${rel}`);
    }
  }
  if (errors.length) return { valid: false, errors };

  const bruts = ranci(arrel, dia);
  if (bruts.length) {
    errors.push(`Escriptori sense classificar: ${bruts.length} document(s) de jornades anteriors encara damunt la taula (${bruts.map((d) => d.nom).join(', ')}). Arxiva'ls amb: node tooling/gates/porta-olivera.mjs --arxiva, o declara'ls vius davall de «## Activitat en curs» a ${INDEX}`);
  }

  const bustia = safata(arrel);
  if (bustia.elements.length) {
    errors.push(`Safata d'entrada amb ${bustia.elements.length} element(s) (${bustia.carpeta}: ${bustia.elements.slice(0, 5).join(', ')}${bustia.elements.length > 5 ? '…' : ''}). La Safata s'ha de buidar sempre (AGENTS §12).`);
  }

  const anc = ancoratge(arrel);
  if (anc.senseAncora.length) errors.push(`Sense àncora a l’índex: ${anc.senseAncora.join(', ')}`);
  if (anc.fantasma.length) errors.push(`Àncores a documents absents: ${anc.fantasma.join(', ')}`);

  return { valid: errors.length === 0, errors };
}

/** Les tres comprovacions de la transició Pla → Petorreta: la taula, el pla i la secció 0. */
export function checkOlivera(arrel = arrelPerDefecte(), { contingut = null, dia = avui() } = {}) {
  const errors = [...checkTaula(arrel, { dia }).errors];

  if (!plaDeHui(arrel, dia).length) {
    errors.push(`Cap Pla d'Implementació de hui (${dia}) a l'Escriptori. Les altres IAs arriben a una habitació sense pissarra. Genera'l abans: node tooling/wiki/document.mjs context --turn-id ID --route pla.implementacio --file ${ESCRIPTORI}/${dia}_HHMM_pla_implementacio_COGNOM.md`);
  }

  if (typeof contingut === 'string') {
    const section = SECCIO_ZERO.exec(contingut);
    if (!section) {
      errors.push("La petorreta no porta la secció 0: «0. Abans de generar (per a l'autor, no per al destinatari)» o «0. Preflight», com la plantilla prompt_local.md. És la precondició d'higiene i ha de viatjar dins del document, no a la memòria de qui l'escriu.");
    } else if (/^[ \t]*[-*+][ \t]+\[[ \t]\]/m.test(section[1])) {
      errors.push('La secció 0 té caselles sense marcar. Cap petorreta ix del Mas amb la llista a mitges.');
    }
  }

  return { valid: errors.length === 0, errors };
}

/** És una petorreta de l'Escriptori? Només eixe cas dispara la porta. */
export function esPetorreta(rel) {
  const pla = rel.split(path.sep).join('/');
  if (!pla.startsWith(`${ESCRIPTORI}/`)) return false;
  if (pla.slice(ESCRIPTORI.length + 1).includes('/')) return false;
  const m = NOM.exec(path.basename(pla));
  return !!m && /^(prompt|macro_prompt|micro_prompt|petorreta)_/.test(m[3]);
}

/* ── Hook ─────────────────────────────────────────────────────────────────── */

/**
 * Una redirecció de shell escriu sense passar per cap eina de fitxers, i eixa és
 * la via per la qual els documents d'aquesta jornada van arribar al disc sense
 * rebut. Ací només mirem el destí: si apunta a una petorreta de l'Escriptori,
 * la porta actua igual que amb una escriptura normal.
 */
export function destiDeShell(ordre) {
  if (typeof ordre !== 'string') return null;
  const m = /(?:>>?|\|\s*tee(?:\s+-a)?)\s*(?:'([^']+)'|"([^"]+)"|(\S+))/.exec(ordre);
  const desti = m && (m[1] || m[2] || m[3]);
  return desti && esPetorreta(desti.replace(/^\.\//, '')) ? desti : null;
}

function rutaIContingut(payload) {
  const ti = payload.tool_input;
  const ta = payload.toolArgs;
  const dialecte = ti ? 'claude' : 'antigravity';
  const fitxer = ti?.file_path || ti?.notebook_path || ta?.TargetFile
    || destiDeShell(ti?.command || ta?.Command || ta?.CommandLine) || null;
  const contingut = typeof ti?.content === 'string' ? ti.content
    : typeof ta?.CodeContent === 'string' ? ta.CodeContent
      : null;
  return { dialecte, fitxer, contingut };
}

export function checkPayload(payload, arrel = arrelPerDefecte()) {
  if (!payload || typeof payload !== 'object' || !payload.tool_name || (!payload.tool_input && !payload.toolArgs)) return {code: 2, errors: ['Payload de hook incomplet']};
  const { dialecte, fitxer, contingut } = rutaIContingut(payload);
  if (!fitxer) {
    const reads = ['Read', 'Glob', 'Grep', 'read_file', 'view_file', 'list_dir', 'grep_search', 'search_code'];
    return reads.includes(payload.tool_name) ? {code: 0, errors: []} : {code: 2, errors: ['Hook sense destí verificable; usa hooks-local per a shell i eines no documentals']};
  }
  const rel = path.isAbsolute(fitxer) ? path.relative(arrel, fitxer) : fitxer;
  if (!esPetorreta(rel)) return { code: 0, errors: [] };
  if (typeof contingut !== 'string') return {code: 2, errors: ['Petorreta sense contingut complet verificable; usa escriptura documental explícita'], file: rel};
  const r = checkOlivera(arrel, { contingut });
  return { code: r.valid ? 0 : (dialecte === 'claude' ? 2 : 1), errors: r.errors, file: rel };
}

/* ── Arxivat explícit ─────────────────────────────────────────────────────── */

/**
 * Què mouria `--arxiva`. Sense noms: els rancis (jornades anteriors, no declarats
 * vius). Amb noms: exactament eixos documents, també d'avui. Cada nom es valida
 * abans de moure res, i un sol nom dolent atura el lot sencer: subcarpetes, noms
 * que no són a la taula i categories que no són de torn. L'índex, els recursos i
 * les notes es queden on són, i per nom tampoc ixen.
 */
export function arxivables(arrel = arrelPerDefecte(), { noms = [], dia = avui() } = {}) {
  if (!noms.length) return ranci(arrel, dia);
  const inv = inventari(arrel);
  const triats = [];
  for (const cru of noms) {
    const pla = String(cru).split('\\').join('/').replace(/^\.\//, '');
    const solt = pla.startsWith(`${ESCRIPTORI}/`) ? pla.slice(ESCRIPTORI.length + 1) : pla;
    if (!solt || solt.includes('/')) {
      throw new Error(`--nom ${cru}: només s'arxiven per nom documents solts del primer nivell de ${ESCRIPTORI}; les subcarpetes (Safata, 01_produccio, 02_investigacio_ia) queden fora`);
    }
    const nom = solt.endsWith('.md') ? solt : `${solt}.md`;
    const d = inv.find((x) => x.nom === nom);
    if (!d) throw new Error(`--nom ${cru}: no és cap document solt de ${ESCRIPTORI} amb nom aammdd_hhmm_categoria_titol.md`);
    if (!TRANSITORIES.test(d.categoria)) {
      throw new Error(`--nom ${cru}: la categoria «${d.categoria}» no és de torn; per nom només ixen prompts, petorretes, auditories, informes, bundles, plans, actes i tasques`);
    }
    if (!triats.includes(d)) triats.push(d);
  }
  return triats;
}

/** Trasllat a l'arxiu. Amb `sec` només respon què faria: cap fitxer mogut ni índex tocat. */
export function arxiva(arrel = arrelPerDefecte(), { noms = [], sec = false, dia = avui() } = {}) {
  const bruts = arxivables(arrel, { noms, dia });
  if (!bruts.length) return { moguts: [], index: false, sec };
  const desti = path.join(arrel, ARXIU);

  if (sec) {
    const moguts = bruts.map((d) => ({ ...d, nota: fs.existsSync(path.join(desti, d.nom)) ? 'simulació: ja existix a l’arxiu; no es mouria' : 'simulació: es mouria' }));
    return { moguts, index: false, sec };
  }

  fs.mkdirSync(desti, { recursive: true });
  const moguts = [];
  for (const d of bruts) {
    const origen = path.join(arrel, d.rel);
    const final = path.join(desti, d.nom);
    if (fs.existsSync(final)) { moguts.push({ ...d, nota: 'ja existia a l’arxiu; no es sobreescriu' }); continue; }
    fs.renameSync(origen, final);
    moguts.push({ ...d, nota: 'mogut' });
  }

  // Despenjar les àncores dels documents que ja no viuen a l'Escriptori.
  const indexPath = path.join(arrel, INDEX);
  let tocat = false;
  if (fs.existsSync(indexPath)) {
    const noms = new Set(moguts.filter((m) => m.nota === 'mogut').map((m) => m.nom.replace(/\.md$/, '')));
    const original = fs.readFileSync(indexPath, 'utf8');
    const prose = prosaIndex(original);
    const removals = [...prose.matchAll(/\[\[([^\]]+)\]\]/g)]
      .filter(match=>noms.has(nomPrimerNivell(referent(match[1]))))
      .map(match=>({start:match.index,end:match.index+match[0].length}));
    // Només una línia composta íntegrament per la seua àncora pot desaparéixer.
    // En taula, prosa o línia compartida lleva el token, preservant la resta.
    let offset = 0;
    const updated = original.split(/(?<=\n)/).map(line=>{
      const start = offset; offset += line.length;
      const selected = removals.filter(item=>item.start>=start && item.end<=start+line.length);
      if (!selected.length) return line;
      let clean = line;
      for (const item of selected.reverse()) clean=clean.slice(0,item.start-start)+clean.slice(item.end-start);
      return /^[ \t]*(?:[-*][ \t]*)?(?:\r?\n)?$/.test(clean) ? '' : clean;
    }).join('');
    if (updated !== original) {
      fs.writeFileSync(indexPath, updated, 'utf8');
      tocat = true;
    }
  }
  return { moguts, index: tocat, sec };
}

/* ── CLI ──────────────────────────────────────────────────────────────────── */

const US = 'Ús: porta-olivera.mjs [--informe] | --hook | --arxiva [--nom FITXER.md]... [--sec]';

/** Banderes de la línia d'ordres. Una bandera desconeguda no es llig com a informe: falla. */
function opcions(argv) {
  const o = { informe: false, hook: false, arxiva: false, sec: false, noms: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--informe') o.informe = true;
    else if (a === '--hook') o.hook = true;
    else if (a === '--arxiva') o.arxiva = true;
    else if (a === '--sec') o.sec = true;
    else if (a === '--nom' || a.startsWith('--nom=')) {
      const valor = a === '--nom' ? argv[++i] : a.slice('--nom='.length);
      if (!valor || valor.startsWith('--')) throw new Error(`--nom necessita el nom d'un document. ${US}`);
      o.noms.push(valor);
    } else throw new Error(`Argument desconegut: ${a}. ${US}`);
  }
  if ([o.informe, o.hook, o.arxiva].filter(Boolean).length > 1) throw new Error(`Tria un sol mode. ${US}`);
  if ((o.noms.length || o.sec) && !o.arxiva) throw new Error(`--nom i --sec només valen amb --arxiva. ${US}`);
  return o;
}

function informe(arrel, dia = avui()) {
  const taula = checkTaula(arrel, { dia });
  if (taula.errors.some(error => error.startsWith("Estructura de l'Escriptori"))) {
    for (const error of taula.errors) console.error(`[Porta Olivera] ${error}`);
    return 1;
  }
  const docs = inventari(arrel);
  const presents = new Set(docs.map((d) => d.nom.replace(/\.md$/, '')));
  const viu = [...vius(arrel)].filter((n) => presents.has(n)).sort();
  const bruts = ranci(arrel, dia);
  const bustia = safata(arrel);
  const anc = ancoratge(arrel);
  const pla = plaDeHui(arrel, dia);
  console.log(`[Porta Olivera] Escriptori: ${docs.length} documents solts.`);
  console.log(viu.length
    ? `🌿 Declarats vius a «## Activitat en curs» (es conserven): ${viu.join(', ')}`
    : '🌿 Cap document de la taula declarat viu a «## Activitat en curs».');
  if (bruts.length) {
    console.log(`❌ ${bruts.length} de jornades anteriors sense declarar vius (han d'anar a ${ARXIU}/):`);
    for (const d of bruts) console.log(`   · ${d.nom}`);
  } else console.log('✅ Cap document consumit de jornades anteriors.');
  console.log(bustia.elements.length ? `❌ Safata d'entrada amb ${bustia.elements.length} element(s): ${bustia.elements.join(', ')}` : "✅ Safata d'entrada buida.");
  if (anc.senseAncora.length) console.log(`❌ Sense àncora a l'índex: ${anc.senseAncora.join(', ')}`);
  if (anc.fantasma.length) console.log(`❌ Àncores a documents absents (fan caure la porta): ${anc.fantasma.join(', ')}`);
  console.log(pla.length
    ? `ℹ️ Pla d'Implementació de hui: ${pla.map((d) => d.nom).join(', ')}`
    : "ℹ️ Cap Pla d'Implementació de hui: el demana l'escriptura d'una petorreta, no l'Escriptori net.");
  return checkTaula(arrel, { dia }).valid ? 0 : 1;
}

function main(argv = process.argv.slice(2)) {
  const o = opcions(argv);
  const arrel = arrelPerDefecte();

  if (o.arxiva) {
    const r = arxiva(arrel, { noms: o.noms, sec: o.sec });
    if (o.sec) console.log('[Porta Olivera] Simulació (--sec): no es mou cap fitxer ni es toca l’índex.');
    if (!r.moguts.length) console.log('[Porta Olivera] Res a arxivar.');
    for (const m of r.moguts) console.log(`   · ${m.nom} → ${ARXIU}/ (${m.nota})`);
    if (r.index) console.log(`   · ${INDEX} actualitzat.`);
    if (r.moguts.some((m) => m.nota === 'mogut')) console.log('   Si algun portava rebut de torn: node tooling/wiki/document.mjs handoff --turn-id ID --file ORIGEN --to DESTÍ');
    process.exitCode = !o.sec && r.moguts.some(m=>m.nota !== 'mogut') ? 1 : 0;
    return;
  }

  if (!o.hook) { process.exitCode = informe(arrel); return; }

  // Mode hook: sense payload no hi ha res a jutjar, i no es pot fingir un verd.
  if (tty.isatty(0)) {
    console.error('[PORTA-OLIVERA] --hook espera el payload JSON per stdin; des d’un terminal usa el mode informe (sense bandera).');
    process.exitCode = 2;
    return;
  }
  const raw = fs.readFileSync(0, 'utf8');
  if (!raw.trim()) {
    console.error('[PORTA-OLIVERA] --hook amb payload buit; cap comprovació executada.');
    process.exitCode = 2;
    return;
  }

  // Un payload il·legible no acredita cap comprovació: falla tancat.
  let result;
  try { result = checkPayload(JSON.parse(raw), arrel); }
  catch (e) {
    console.error(`[PORTA-OLIVERA] payload il·legible (${e.message}); cap comprovació executada.`);
    result = { code: 2, errors: ['Payload il·legible: cap autorització'] };
  }

  if (result.errors.length) {
    console.error(`[PORTA-OLIVERA] BLOQUEIG · ${result.file ?? '(sense destí)'}\n${result.errors.map((e) => `- ${e}`).join('\n')}\nLa Reunió a l'Olivera comença amb la taula classificada i el Pla damunt.`);
  }
  process.exitCode = result.code;
}

// `import.meta.url` porta el camí REAL i `process.argv[1]` el camí tal com
// s'ha escrit: sota un symlink (/var cap a /private/var a macOS, i qualsevol
// fixture de proves a os.tmpdir()) no coincidixen, el mòdul es carrega en
// silenci i la porta ix 0 sense comprovar res. Resoldre el symlink és el que
// fa que la guarda parle sempre.
if (esMain(import.meta.url)) {
  try { main(); } catch (e) { console.error(e.message); process.exitCode = 2; }
}

#!/usr/bin/env node
/** antigravity-hook.mjs — la Porta Olivera i la Plantilla viva, dites en el dialecte d'Antigravity.
 *
 *  El problema, dit sense adornar-lo: MarIA escriu des d'Antigravity IDE i cap
 *  porta la veia. `.agents/hooks.json` era al camí bo, però amb un format, un
 *  payload, un contracte d'eixida i un directori de treball que l'IDE no parla.
 *  La regla que havia de disparar quan MarIA escriu un prompt vivia en canals que
 *  MarIA no té davant en eixe moment.
 *
 *  Contracte (documentació local de l'IDE 2.5.5, llegida el 260930):
 *    ~/.gemini/antigravity-ide/builtin/skills/agy-customizations/docs/hooks.md
 *    · `.agents/hooks.json`: cada clau de primer nivell és un hook amb nom.
 *    · L'ordre corre amb `sh -c` des del directori que conté hooks.json
 *      (`.agents/`): per això les ordres fan `cd ..` abans de cridar node.
 *    · Entrada per stdin, JSON en camelCase. PreToolUse porta
 *      `{toolCall: {name, args}, stepIdx, …}`; PreInvocation, `{invocationNum, …}`.
 *    · Eixida per stdout, JSON. PreToolUse → `{decision: allow|deny|ask|force_ask,
 *      reason}`; PreInvocation → `{injectSteps: [{ephemeralMessage}]}` o `{}`.
 *
 *  Què fa:
 *    pre-tool        · escriure un prompt, una petorreta o un pla al primer nivell
 *                      de l'Escriptori: `deny` si la Plantilla viva o la Porta
 *                      Olivera hi troben errors, amb el motiu i la via de sortida;
 *                    · `run_command` destructiu que toca Escriptori/governança: `force_ask` (el
 *                      trasllat a mà deixa àncores fantasma a l'índex);
 *                    · `run_command` que redirigix (`>`, `>>`, `| tee`) a un
 *                      document del primer nivell: `force_ask` (el contingut no es pot
 *                      jutjar, i és la via per on van nàixer documents sense rebut);
 *                    · la resta: `allow`.
 *    pre-invocation  · si l'Escriptori no passa `checkTaula` (definició única,
 *                      AGENTS §0.1), injecta un missatge efímer curt amb l'ordre
 *                      observa → actua → verifica → informa.
 *
 *  No hi ha `Stop`: un `continue` mal comptat és un bucle, i tancar el torn no és
 *  feina d'un hook d'escriptura.
 *
 *  Seguretat de funcionament:
 *    · Qualsevol error en pre-tool torna `ask`: ni `allow` cec ni `deny` cec.
 *    · Interruptor d'apagada: si existix `.agents/runtime/antigravity-hook.off`,
 *      torna `allow` (o `{}`) sense comprovar ni traçar res. És del Mestre: una
 *      escriptura de MarIA a l'interruptor, a hooks.json o a este fitxer pregunta.
 *    · Traça d'una línia per invocació a `.agents/runtime/antigravity-hook.log`
 *      (fora de git per `*.log`): és l'única acreditació que l'IDE executa el hook.
 *    · stdin només es llig si no és un terminal: executat a mà no es penja (la
 *      lliçó de la porta Olivera antiga, que esperava un EOF que no arribava).
 *
 *  Nucli pur: `preTool` i `preInvocation` reben les portes per paràmetre. Els
 *  imports reals (`./porta-olivera.mjs`, `./porta-reflex.mjs`,
 *  `./porta-plantilla-viva.mjs`) es fan amb `import()` dins de `main()`, i només
 *  quan la decisió els necessita: un `view_file` no paga cap càrrega, i el nucli
 *  es prova amb portes falses.
 *
 *  Ús (des de l'arrel; l'IDE ho fa amb `cd ..` des de `.agents/`):
 *    node tooling/gates/antigravity-hook.mjs pre-tool        < payload.json
 *    node tooling/gates/antigravity-hook.mjs pre-invocation  < payload.json
 */
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { knownPureRead, SECURITY_PATHS, mutationPath } from './mutation-policy.mjs';
import { documentArgv } from '../documental/command-policy.mjs';

export const DESK = '_wiki_de_poble/04_escriptori';
export const INTERRUPTOR = '.agents/runtime/antigravity-hook.off';
export const TRACA = '.agents/runtime/antigravity-hook.log';
export const MODES = Object.freeze(['pre-tool', 'pre-invocation']);

/* Noms d'eina d'escriptura d'Antigravity. La documentació només acredita
   `run_command`, `view_file` i `browser_*`; estos tres noms, i les claus
   TargetFile, CodeContent i ReplacementChunks, són els del dialecte que ja parla
   porta-reflex.mjs. Per això també compta com a escriptura qualsevol eina que
   porte un argument de contingut, es diga com es diga: un nom nou no escapa. */
const ESCRIPTURA = new Set(['write_to_file', 'replace_file_content', 'multi_replace_file_content']);
const ARGS_CONTINGUT = Object.freeze(['CodeContent', 'ReplacementChunks', 'ReplacementContent', 'TargetContent']);

/* Peces que governen este mateix hook. Tocar-les és decisió del Mestre. */
const AUTOPROTEGITS = new Set(['.agents/hooks.json', 'tooling/gates/antigravity-hook.mjs', INTERRUPTOR]);

const ALLOW = Object.freeze({ decision: 'allow' });
const ask = (reason) => ({ decision: 'ask', reason });
const forceAsk = (reason) => ({ decision: 'force_ask', reason });
const MAX_ERRORS = 12;

const VIA_OLIVERA = 'node tooling/gates/porta-olivera.mjs';
const MOTIU_MV = `Trasllat a mà dins de l'Escriptori: deixa àncores fantasma a l'índex i no avisa cap rebut. Via canònica (AGENTS §0.1): ${VIA_OLIVERA} --arxiva [--nom aammdd_hhmm_categoria_titol.md] [--sec].`;

export function retalla(text, max = 300) {
  const t = String(text ?? '');
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}

/**
 * Ruta relativa a l'arrel amb `/`, o null si ix del repositori. És lèxica: un
 * symlink que escapa el jutja porta-reflex (protectedPath) quan cal reconstruir.
 */
export function relatiu(root, cami, base = root) {
  if (typeof cami !== 'string' || !cami) return null;
  const r = path.relative(root, path.resolve(base, cami));
  if (!r || r === '..' || r.startsWith(`..${path.sep}`) || path.isAbsolute(r)) return null;
  return r.split(path.sep).join('/');
}

const alPrimerNivell = (rel) => path.posix.dirname(rel) === DESK;
const esMd = (rel) => /\.md$/i.test(rel);
const zonaHumana = (rel) => rel.toLowerCase().startsWith(`${DESK}/01_produccio/`);
const governat = rel => SECURITY_PATHS.some(dir=>rel.toLowerCase()===dir || rel.toLowerCase().startsWith(`${dir}/`))
  || /^(?:agents|claude)\.md$|^package(?:-lock)?\.json$/i.test(rel);
const argsDe = (crida) => (crida?.args && typeof crida.args === 'object' && !Array.isArray(crida.args) ? crida.args : {});

export function esEscriptura(nom, args = {}) {
  return ESCRIPTURA.has(nom) || ARGS_CONTINGUT.some((k) => Object.hasOwn(args, k));
}

/**
 * Antigravity edita per trossos amb StartLine/EndLine, i porta-reflex rebutja
 * les edicions per línies perquè no en coneix la semàntica exacta. Un tros sense
 * AllowMultiple dona el mateix resultat sense les línies SI el text buscat només
 * apareix una vegada al document, i eixa unicitat ja l'exigix porta-reflex: si
 * apareix dues voltes, falla i el hook pregunta. Amb AllowMultiple les línies
 * limiten l'abast i no es poden llevar: es deixen, i porta-reflex les rebutja.
 */
export function sensePosicions(args) {
  const lleva = (c) => (c && typeof c === 'object' && c.AllowMultiple !== true
    ? Object.fromEntries(Object.entries(c).filter(([k]) => k !== 'StartLine' && k !== 'EndLine'))
    : c);
  const out = { ...lleva(args) };
  if (Array.isArray(args.ReplacementChunks)) out.ReplacementChunks = args.ReplacementChunks.map(lleva);
  return out;
}

/** Nom literal de shell: resol cometes/escapes, mai executa expansions. */
function shellLiteral(raw) {
  let value='',quote=null;
  for(let i=0;i<raw.length;i++) {
    const character=raw[i];
    if(quote==="'") { if(character===quote)quote=null;else value+=character;continue; }
    if(character==='"' || (!quote && character==="'")) { quote=quote?null:character;continue; }
    if(character==='\\') {
      const next=raw[++i];if(next===undefined)return null;
      if(quote==='"' && !/[$`"\\]/.test(next))value+='\\';
      value+=next;continue;
    }
    if(character==='$'||character==='`')return null;
    value+=character;
  }
  return quote?null:value;
}
function redirectionWords(command) {
  const targets=[];
  for(const match of command.matchAll(/(?:>>?|\|\s*tee(?:\s+-a)?(?:\s+--)?)\s*((?:'[^']*'|"(?:\\.|[^"\\])*"|\\.|[^\s;&|<>])+)/g)) {
    targets.push(match[1]);
  }
  // tee pot escriure diversos destins: cada nom literal passa per la mateixa porta.
  for(const tee of command.matchAll(/\|\s*tee(?:\s+-a)?(?:\s+--)?\s+([^;&|\n]+)/g)) {
    for(const word of tee[1].matchAll(/(?:'[^']*'|"(?:\\.|[^"\\])*"|\\.|[^\s;&|<>])+/g)) {
      const literal=shellLiteral(word[0]);if(!literal || !literal.startsWith('-'))targets.push(word[0]);
    }
  }
  return [...new Set(targets)];
}
const redirectionTargets=command=>redirectionWords(command).map(shellLiteral).filter(Boolean);

/** Destins de les redireccions d'una ordre que cauen al primer nivell de l'Escriptori. */
export function redireccionsAlTaulell(ordre, root, cwd = root) {
  const out = [];
  for (const target of redirectionTargets(ordre)) {
    const rel = relatiu(root, target, cwd);
    if (rel && alPrimerNivell(rel) && esMd(rel)) out.push(rel);
  }
  return out;
}

/* ── Nucli pur ────────────────────────────────────────────────────────────── */

function preShell(args, root) {
  const ordre = typeof args.CommandLine === 'string' ? args.CommandLine : typeof args.Command === 'string' ? args.Command : null;
  if (ordre === null) return ask('Hook Olivera: run_command sense CommandLine; cap comprovació feta.');
  if (typeof args.CommandLine === 'string' && typeof args.Command === 'string' && args.CommandLine !== args.Command) {
    return forceAsk('Hook Olivera: CommandLine i Command divergents; cap ordre privilegiada acreditada.');
  }
  if (ordre.includes('antigravity-hook.off')) {
    return forceAsk(`L'interruptor ${INTERRUPTOR} és del Mestre: apagar el hook necessita el seu permís.`);
  }
  const cwd = typeof args.Cwd === 'string' && args.Cwd ? path.resolve(root, args.Cwd) : root;
  const cwdRel = (relatiu(root, cwd) ?? '').toLowerCase();
  // Les lectures elementals ja aprovades no es convertixen en preguntes perquè
  // el patró cercat diga «rm» o esmente una ruta governada.
  if (knownPureRead({tool_name:'run_command',tool_input:{command:ordre}},root)) return ALLOW;
  // Un argument literal d'una CLI governada pot citar «rm .» com a text.
  // L'argv no admet composició ni expansió; l'autoritat continua a l'executor/CLI.
  try {
    const argv=documentArgv(ordre);
    if (argv[0]==='node' && ['tooling/wiki/document.mjs','tooling/gates/obrir_torn.mjs','tooling/gates/porta-olivera.mjs','tooling/gates/executor-mutacio.mjs'].includes(argv[1])) return ALLOW;
  } catch { /* ordre composta: mai una excepció per prefix */ }
  const lexicalRisk = ordre.replace(/['"\\]/g,'');
  const riskText = lexicalRisk.toLowerCase();
  const mentions = dir => new RegExp(`(?:^|[\\s/])${dir.replaceAll('.','[.]')}(?=$|[\\s/;&|()])`).test(riskText);
  const tocaTaulell = mentions('04_escriptori') || cwdRel === DESK || cwdRel.startsWith(`${DESK}/`);
  const enclosesProtected = directory => [DESK,...SECURITY_PATHS].some(dir=>{
    const rel=path.relative(directory,path.join(root,dir));
    return rel==='' || (rel!=='..' && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel));
  });
  const ancestorRisk = lexicalRisk.split(/[ \t;&|]+/).some(word=>word && !word.startsWith('-') && enclosesProtected(word==='*'?cwd:path.resolve(cwd,word)))
    || lexicalRisk.endsWith(root) || lexicalRisk.endsWith(`${root}/`) || lexicalRisk.includes(`${root} `);
  const tocaGovern = ancestorRisk || SECURITY_PATHS.some(dir=>mentions(dir) || cwdRel===dir || cwdRel.startsWith(`${dir}/`)) || /(?:AGENTS|CLAUDE)\.md|package(?:-lock)?\.json/i.test(riskText);
  const destructiva = /(?:^|[\s;&|(`])(?:\/(?:[^/\s`]+\/)*)?(?:rm|mv|unlink|rmdir|truncate)(?=[\s`]|$)/.test(riskText);
  if (tocaTaulell && destructiva) return forceAsk(`${MOTIU_MV}${tocaGovern?' Si afecta governança, necessita executor-mutacio.mjs amb pla exacte i lease.':''}`);
  if (tocaGovern && destructiva) return forceAsk('Destrucció o trasllat de governança: necessita autoritat explícita; usa executor-mutacio.mjs amb pla exacte i lease.');
  // Un intèrpret inline amb destí explícit no és una via documental ni un lease.
  if ((tocaTaulell || tocaGovern) && /(?:^|[\s;&|('"`])(?:\/(?:[^/\s'"`]+\/)*)?(?:node|python[0-9.]*|perl|ruby|sh|bash|zsh)(?:[ \t]+[^;&|]*)?[ \t]-(?:e|c|p)(?=[ \t]|$)/.test(lexicalRisk)) {
    return forceAsk('Intèrpret inline amb ruta protegida: necessita autoritat explícita; usa la via documental o executor-mutacio amb pla i lease.');
  }
  if((tocaTaulell||tocaGovern) && redirectionWords(ordre).some(raw=>shellLiteral(raw)===null)) {
    return forceAsk('Redirecció amb expansió no verificable i ruta protegida: cap destí ni autoritat acreditats.');
  }
  for (const target of redirectionTargets(ordre)) {
    const rel=relatiu(root,target,cwd);
    if(!rel)continue; // /dev/null i artefactes fora del repo ja preaprovats.
    if(governat(rel)||zonaHumana(rel))return forceAsk(`Redirecció a ${rel}: ruta protegida; usa la via amb autoritat explícita.`);
    try {
      const physical=mutationPath(root,target,cwd);
      if(governat(physical)||zonaHumana(physical)||(alPrimerNivell(physical)&&esMd(physical)))return forceAsk(`Redirecció a ${physical}: ruta física protegida; usa node tooling/wiki/document.mjs context → create o executor-mutacio.mjs amb pla exacte i lease.`);
    } catch(error) { return forceAsk(`Destí de redirecció protegit: ${retalla(error.message)}`); }
  }
  const redir = redireccionsAlTaulell(ordre, root, cwd);
  if (redir.length) {
    return forceAsk(`Escriptura per shell a ${redir.join(', ')}: no passa per cap porta ni deixa rebut. Un document de l'Escriptori s'escriu amb l'eina d'edició, i un prompt o un pla naix de node tooling/wiki/document.mjs context → create.`);
  }
  return ALLOW;
}

function motiuDeny(fitxer, errors) {
  const llista = errors.slice(0, MAX_ERRORS).map((e) => `- ${retalla(e)}`);
  if (errors.length > MAX_ERRORS) llista.push(`- … i ${errors.length - MAX_ERRORS} més`);
  return [
    `Porta Olivera · ${fitxer}`,
    ...llista,
    `Resol-ho ara (AGENTS §0.1): observa amb ${VIA_OLIVERA}, declara els vius a «## Activitat en curs» o arxiva amb --arxiva, i fes nàixer el document de la plantilla (node tooling/wiki/document.mjs context → create).`,
  ].join('\n');
}

function preEscriptura(args, { root, portes }) {
  const cami = typeof args.TargetFile === 'string' && args.TargetFile ? args.TargetFile : null;
  if (!cami) return ask("Hook Olivera: eina d'escriptura sense TargetFile; cap comprovació feta.");
  const rel = relatiu(root, cami);
  if (rel === null) return ALLOW; // fora del repositori: artefactes propis de l'IDE (~/.gemini/…)
  if (zonaHumana(rel)) return forceAsk(`${rel} és a la zona humana (01_produccio): només amb ordre directa i explícita del Mestre (AGENTS §12).`);
  if (AUTOPROTEGITS.has(rel)) return forceAsk(`${rel} governa el hook d'Antigravity: canviar-lo és decisió del Mestre.`);
  if (governat(rel)) return forceAsk(`${rel} és governança: usa executor-mutacio.mjs amb pla exacte i lease; l’eina directa no acredita autoritat.`);
  // Una àlies en src pot apuntar a governança o eixir de l'arrel. Reusa la
  // mateixa resolució física i defensa de hardlinks que la política de mutació.
  try {
    const physical = mutationPath(root,cami);
    if (governat(physical) || zonaHumana(physical)) return forceAsk(`${physical} és una ruta física protegida; l'àlies no acredita autoritat.`);
  } catch (error) { return forceAsk(`Ruta d'escriptura protegida: ${retalla(error.message)}`); }
  if (!alPrimerNivell(rel) || !esMd(rel)) return ALLOW;
  if (!portes) throw new Error('portes no carregades per a una escriptura a l’Escriptori');

  const nom = path.posix.basename(rel);
  if (!portes.esPetorreta(rel) && !portes.vigilat(nom)) return ALLOW;
  if (args.AllowMultiple === true && (args.StartLine !== undefined || args.EndLine !== undefined)) {
    return ask(`Hook Olivera · ${rel}: edició AllowMultiple limitada per línies; no es pot reconstruir el document. Escriu-lo sencer o demana permís.`);
  }

  let op;
  try { op = portes.operacio({ toolArgs: sensePosicions(args), cwd: root }); }
  catch (e) { return ask(`Hook Olivera · ${rel}: ${retalla(e.message)}. No es pot reconstruir el document; escriu-lo sencer (write_to_file) o demana permís.`); }
  if (!op || op.fora || typeof op.contingut !== 'string') {
    return ask(`Hook Olivera · ${rel}: la porta documental no reconeix la ruta; cap comprovació feta.`);
  }

  const fitxer = op.fitxer;
  const errors = [];
  if (portes.esPetorreta(fitxer)) errors.push(...portes.olivera(op.contingut));
  errors.push(...portes.plantilla(fitxer, op.contingut).map((e) => `[Plantilla viva] ${e}`));
  return errors.length ? { decision: 'deny', reason: motiuDeny(fitxer, errors) } : ALLOW;
}

/** PreToolUse. `portes` només cal quan `calenPortes` ho diu; si falta, llança i el cridador pregunta. */
export function preTool(payload, { root, portes = null } = {}) {
  const crida = payload?.toolCall;
  const nom = crida?.name;
  if (typeof nom !== 'string' || !nom) return ask('Hook Olivera: payload sense toolCall.name; cap comprovació feta.');
  const args = argsDe(crida);
  if (nom === 'run_command') return preShell(args, root);
  if (!esEscriptura(nom, args)) return ALLOW;
  return preEscriptura(args, { root, portes });
}

export function missatgeTaula(errors = []) {
  const llista = Array.isArray(errors) ? errors : [];
  const mostra = llista.slice(0, 3).map((e) => retalla(e, 160)).join(' · ');
  const mes = llista.length > 3 ? ` (+${llista.length - 3})` : '';
  return `[Escriptori brut · AGENTS §0.1] ${mostra || 'la porta no diu per què'}${mes}. Resol-ho en este torn, abans de redactar cap prompt o pla: observa (${VIA_OLIVERA}) → actua (declara els vius a «## Activitat en curs», arxiva la resta amb --arxiva, corregix les àncores) → verifica (la porta ix amb 0) → informa (una línia al Mestre).`;
}

/** PreInvocation: la taula neta no diu res; la bruta ho diu una vegada per crida, curt. */
export function preInvocation({ portes = null } = {}) {
  if (!portes) throw new Error('portes no carregades per a comprovar la taula');
  const r = portes.taula();
  if (!r || typeof r.valid !== 'boolean') throw new Error('checkTaula ha tornat un resultat il·legible');
  return r.valid ? {} : { injectSteps: [{ ephemeralMessage: missatgeTaula(r.errors) }] };
}

/** Quines portes cal carregar abans de decidir: 'taula', 'escriptura' o null. */
export function calenPortes(mode, payload, root) {
  if (mode === 'pre-invocation') return 'taula';
  if (mode !== 'pre-tool') return null;
  const crida = payload?.toolCall;
  const nom = crida?.name;
  const args = argsDe(crida);
  if (typeof nom !== 'string' || nom === 'run_command' || !esEscriptura(nom, args)) return null;
  const rel = relatiu(root, args.TargetFile);
  return rel && alPrimerNivell(rel) && esMd(rel) ? 'escriptura' : null;
}

export function decidix(mode, payload, ctx) {
  if (mode === 'pre-tool') return preTool(payload, ctx);
  if (mode === 'pre-invocation') return preInvocation(ctx);
  throw new Error(`mode desconegut «${mode ?? ''}»`);
}

/** Resposta davant qualsevol error: pregunta (pre-tool) o avisa que no s'ha pogut mirar (pre-invocation). */
export function perError(mode, error) {
  const m = retalla(error?.message ?? error);
  return mode === 'pre-invocation'
    ? { injectSteps: [{ ephemeralMessage: `[Hook Olivera] no s'ha pogut comprovar l'Escriptori (${m}). Comprova-ho a mà amb ${VIA_OLIVERA} i avisa el Mestre.` }] }
    : ask(`Hook Olivera: error intern (${m}); cap comprovació feta.`);
}

/* ── Procés ───────────────────────────────────────────────────────────────── */

async function carregaPortes(tipus, root) {
  const olivera = await import('./porta-olivera.mjs');
  if (tipus === 'taula') {
    if (typeof olivera.checkTaula !== 'function') throw new Error('porta-olivera.mjs no exporta checkTaula: cal la porta v3');
    return { taula: () => olivera.checkTaula(root) };
  }
  const [reflex, viva] = await Promise.all([import('./porta-reflex.mjs'), import('./porta-plantilla-viva.mjs')]);
  return {
    esPetorreta: (rel) => olivera.esPetorreta(rel),
    vigilat: (nom) => viva.vigilat(nom),
    operacio: (payload) => reflex.normalitza(payload, root),
    olivera: (contingut) => olivera.checkOlivera(root, { contingut }).errors,
    plantilla: (rel, contingut) => viva.inspeccionaText(root, rel, contingut).errors,
  };
}

function llegeixPayload() {
  if (process.stdin.isTTY) return { payload: null, error: 'stdin és un terminal: cap payload' };
  let raw;
  try { raw = fs.readFileSync(0, 'utf8'); } catch (e) { return { payload: null, error: `stdin il·legible (${e.message})` }; }
  if (!raw.trim()) return { payload: null, error: 'payload buit' };
  try { return { payload: JSON.parse(raw), error: null }; } catch (e) { return { payload: null, error: `payload il·legible (${e.message})` }; }
}

function traca(root, entrada) {
  try {
    const fitxer = path.join(root, TRACA);
    fs.mkdirSync(path.dirname(fitxer), { recursive: true });
    fs.appendFileSync(fitxer, `${JSON.stringify({ t: new Date().toISOString(), ...entrada })}\n`);
  } catch { /* la traça no decidix mai */ }
}

const escriu = (eixida) => process.stdout.write(`${JSON.stringify(eixida)}\n`);

async function main(argv) {
  const mode = argv[0];
  const root = path.resolve(process.env.SDP_ARREL || process.cwd());
  // stdin es buida sempre: l'IDE hi escriu el payload sencer i no ha de trobar la canonada tancada.
  const { payload, error } = llegeixPayload();
  if (fs.existsSync(path.join(root, INTERRUPTOR))) { escriu(mode === 'pre-tool' ? ALLOW : {}); return; }

  let eixida;
  try {
    if (!MODES.includes(mode)) throw new Error(`mode desconegut «${mode ?? ''}»`);
    if (mode === 'pre-tool' && error) throw new Error(error);
    const tipus = calenPortes(mode, payload, root);
    const portes = tipus ? await carregaPortes(tipus, root) : null;
    eixida = decidix(mode, payload, { root, portes });
  } catch (e) {
    eixida = perError(mode, e);
  }

  const args = argsDe(payload?.toolCall);
  traca(root, {
    mode: mode ?? null,
    eina: payload?.toolCall?.name ?? null,
    fitxer: relatiu(root, args.TargetFile) ?? (args.TargetFile ? 'fora del repositori' : null),
    decisio: eixida.decision ?? (eixida.injectSteps ? 'injecta' : 'res'),
    ...(eixida.reason ? { motiu: retalla(eixida.reason, 200) } : {}),
  });
  escriu(eixida);
}

// Mateixa guarda que porta-olivera.mjs: sota un symlink (/var → /private/var a
// macOS) `process.argv[1]` i `import.meta.url` no coincidixen si no es resol el
// camí real, i el mòdul es carregaria en silenci sense decidir res.
function esEntrada() {
  try { return Boolean(process.argv[1]) && import.meta.url === pathToFileURL(fs.realpathSync(process.argv[1])).href; }
  catch { return false; }
}
if (esEntrada()) {
  main(process.argv.slice(2)).catch((e) => escriu(perError(process.argv[2], e)));
}

/** Diagnosi de la incidència de MarIA del 261002: «esborrar i arxivar» a l'Escriptori.
 *
 *  MarIA va deixar l'Escriptori net per força bruta: sis documents d'avui moguts a
 *  mà a `90_arxiu_historic/` i les àncores llevades a mà de l'índex. La traça
 *  `.agents/runtime/antigravity-hook.log` (14:47:53 – 14:50:55Z) en conserva els
 *  estats intermedis; estes proves els reproduïxen en un Mas sintètic.
 *
 *  Convenció: una prova «[DEFECTE Dn]» PASSA hui perquè afirma el comportament
 *  defectuós actual. La reparació l'ha d'invertir (i, aleshores, cal reescriure
 *  l'asserció en positiu). Una prova «[CONTROL]» fixa el que ja funciona i ha de
 *  continuar funcionant després de la reparació.
 *
 *  Totes les fixtures viuen a os.tmpdir(): cap prova toca l'Escriptori real, i
 *  cap dada és real (noms de document sintètics amb la data d'avui o 250101).
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { inventari, vius, ranci, ancoratge, checkTaula, arxivables, arxiva, avui, checkPayload } from '../tooling/gates/porta-olivera.mjs';
import { checkLocal } from '../tooling/gates/hooks-local.mjs';
import { preTool } from '../tooling/gates/antigravity-hook.mjs';
import { SOURCES } from '../tooling/brain/context-local.mjs';
import { checkTurn, handoffDocument, bindPlan } from '../tooling/documental/turns.mjs';
import { fixture, validDoc, writeDoc, REPO } from './helpers/documental.mjs';

const PORTA = fileURLToPath(new URL('../tooling/gates/porta-olivera.mjs', import.meta.url));
const DESK = '_wiki_de_poble/04_escriptori';
const ARXIU = '_wiki_de_poble/90_arxiu_historic';
const INDEX = `${DESK}/00_index_escriptori.md`;
const DIA = avui();
// Una jornada que sempre és anterior a hui.
const VELL = '250101';

function mas(t, linies = ['# Índex', '']) {
  const arrel = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'sdp-olivera-diagnosi-')));
  fs.mkdirSync(path.join(arrel, DESK), { recursive: true });
  fs.writeFileSync(path.join(arrel, INDEX), [].concat(linies).join('\n'));
  t.after(() => fs.rmSync(arrel, { recursive: true, force: true }));
  return arrel;
}
const posa = (arrel, nom, text = '# prova\n') => fs.writeFileSync(path.join(arrel, DESK, nom), text);
const index = (arrel) => fs.readFileSync(path.join(arrel, INDEX), 'utf8');
const aTaula = (arrel, nom) => fs.existsSync(path.join(arrel, DESK, nom));
const aArxiu = (arrel, nom) => fs.existsSync(path.join(arrel, ARXIU, nom));
const sense = (nom) => nom.replace(/\.md$/, '');
const entornSenseArrel = () => { const e = { ...process.env }; delete e.SDP_ARREL; return e; };

/* ── 1. La seqüència de MarIA, estat per estat ────────────────────────────── */

test('[DEFECTE D1+D2] la seqüència del 261002: --arxiva per defecte no veu els d’avui, --nom cau sencer per una «visio» i el trasllat a mà deixa fantasmes', (t) => {
  const g = `${DIA}_0045_pla_implementacio_gestoria.md`;
  const a = `${DIA}_0205_pla_implementacio_arbre_genealogic.md`;
  const v = `${DIA}_0310_visio_arquitectonica_expansio.md`;
  const fp = `${DIA}_1245_pla_implementacio_alarma_fatiga.md`;
  const fr = `${DIA}_1245_prompt_claude_alarma_fatiga.md`;
  const au = `${DIA}_1525_auditoria_claude.md`;
  const sis = [g, a, v, fp, fr, au];
  const arrel = mas(t, [
    '# Índex', '', '## Activitat en curs', '',
    ...[g, a, v, fp, fr].map((n) => `- [[${sense(n)}]]`),
    '', '## Altres enllaços', '',
    `- [[${sense(fp)}]]`, '', `- [[${sense(fr)}]]`, '', `- [[${sense(au)}]]`, ''
  ]);
  for (const n of sis) posa(arrel, n);

  // Abans de netejar, la taula és «neta»: tot ancorat i res d'una jornada anterior.
  assert.equal(checkTaula(arrel).valid, true);

  // D2: el mode per defecte (npm run olivera:arxiva) només mou jornades anteriors.
  assert.deepEqual(ranci(arrel, DIA), []);
  assert.deepEqual(arxiva(arrel).moguts, []);
  for (const n of sis) assert.ok(aTaula(arrel, n), `${n} no s'ha mogut`);

  // D1: per nom, una sola categoria fora de TRANSITORIES («visio») atura el lot sencer.
  assert.throws(() => arxiva(arrel, { noms: sis }), /la categoria «visio» no és de torn/);
  for (const n of sis) assert.ok(aTaula(arrel, n), `${n} continua a la taula després de l'error`);
  // Sense la «visio», els altres cinc sí que eixirien: l'únic bloqueig és la categoria.
  assert.equal(arxivables(arrel, { noms: sis.filter((n) => n !== v) }).length, 5);

  // Traça 14:47:53Z: llevar a mà les àncores d'«Activitat en curs» abans de moure.
  fs.writeFileSync(path.join(arrel, INDEX), index(arrel).replace(/## Activitat en curs\n\n(?:- \[\[[^\]]+\]\]\n)+/, '## Activitat en curs\n\n'));
  const brut = checkTaula(arrel);
  assert.equal(brut.valid, false);
  assert.match(brut.errors.join('\n'), new RegExp(`Sense àncora a l’índex: ${g}, ${a}, ${v}`));

  // Traça 14:49:21Z: trasllat a mà dels sis. Les àncores de baix queden fantasma.
  fs.mkdirSync(path.join(arrel, ARXIU), { recursive: true });
  for (const n of sis) fs.renameSync(path.join(arrel, DESK, n), path.join(arrel, ARXIU, n));
  assert.deepEqual(ancoratge(arrel).fantasma, [sense(fp), sense(fr), sense(au)]);
  assert.equal(checkTaula(arrel).valid, false);
});

test('[CONTROL] l’ús canònic funciona per a categories de torn: --arxiva --nom mou els d’avui i despenja les línies «- [[X]]»', (t) => {
  const p = `${DIA}_1245_prompt_claude_alarma_fatiga.md`;
  const q = `${DIA}_1245_pla_implementacio_alarma_fatiga.md`;
  const arrel = mas(t, ['# Índex', '', '## Activitat en curs', '', `- [[${sense(p)}]]`, `- [[${sense(q)}]]`, '']);
  posa(arrel, p); posa(arrel, q);
  const r = arxiva(arrel, { noms: [p, q] });
  assert.deepEqual(r.moguts.map((m) => m.nota), ['mogut', 'mogut']);
  assert.ok(aArxiu(arrel, p) && aArxiu(arrel, q));
  assert.equal(checkTaula(arrel).valid, true);
});

